<?php
namespace ServSys\Admin;
use ServSys\FlatRate\FlatRateItemRepository;
use ServSys\FlatRate\FlatRatePricingEngine;
use ServSys\ServiceCalls\ServiceCallChargeRepository;
use ServSys\ServiceCalls\ServiceCallChargeService;
use ServSys\Users\Capabilities;
if ( ! defined( 'ABSPATH' ) ) { exit; }
final class ServiceCallChargesPage {
 public function register(): void {add_action('admin_post_servsys_service_call_add_flat_rate_charge',array($this,'add_flat_rate'));add_action('admin_post_servsys_service_call_add_manual_charge',array($this,'add_manual'));}
 public function render(int $service_call_id): void {
  if(!current_user_can(Capabilities::VIEW_SERVICE_CALL_CHARGES)){return;}$repo=new ServiceCallChargeRepository();$rows=$repo->for_service_call($service_call_id);
  echo '<h3>Service Charges</h3><p class="description">Charge prices are snapshots. Later Flat Rate, material-cost, markup, tax, or configuration changes do not alter these rows. Inventory usage is recorded separately and is not consumed by adding a Flat Rate charge.</p>';
  echo '<table class="widefat striped"><thead><tr><th>Source</th><th>Code</th><th>Description</th><th>Price Type</th><th>Qty</th><th>Unit Price</th><th>Extended</th></tr></thead><tbody>';
  if(!$rows){echo '<tr><td colspan="7">No service charges have been recorded for this Service Call.</td></tr>';}
  foreach($rows as $row){echo '<tr><td>'.esc_html('flat_rate'===$row['source_type']?'Flat Rate':'Manual').'</td><td>'.esc_html((string)$row['flat_rate_code_snapshot']).'</td><td>'.esc_html($row['description_snapshot']).'</td><td>'.esc_html((string)$row['price_type_snapshot']).'</td><td>'.esc_html($this->number($row['quantity'])).'</td><td>$'.esc_html(number_format((float)$row['unit_price_snapshot'],2)).'</td><td>$'.esc_html(number_format((float)$row['extended_price'],2)).'</td></tr>';}
  echo '</tbody><tfoot><tr><th colspan="6">Service Charge Total</th><th>$'.esc_html(number_format($repo->total_for_service_call($service_call_id),2)).'</th></tr></tfoot></table>';
  if(!current_user_can(Capabilities::MANAGE_SERVICE_CALL_CHARGES)){return;}$items=(new FlatRateItemRepository())->search('',false);
  echo '<h4>Add Flat Rate Charge</h4><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('servsys_service_call_add_flat_rate_charge_'.$service_call_id);echo '<input type="hidden" name="action" value="servsys_service_call_add_flat_rate_charge"><input type="hidden" name="service_call_id" value="'.esc_attr((string)$service_call_id).'"><p><label>Flat Rate Item<br><select name="flat_rate_item_id" required><option value="">Select item</option>';foreach($items as $item){echo '<option value="'.esc_attr((string)$item['id']).'">'.esc_html($item['code'].' — '.$item['description']).'</option>';}echo '</select></label></p><p><label>Price Type<br><select name="price_type">';foreach(array(FlatRatePricingEngine::PRICE_STANDARD=>'Standard',FlatRatePricingEngine::PRICE_ADDITIONAL=>'Additional Repair',FlatRatePricingEngine::PRICE_AGREEMENT=>'Service Agreement',FlatRatePricingEngine::PRICE_AGREEMENT_ADDITIONAL=>'Agreement Additional',FlatRatePricingEngine::PRICE_COMMERCIAL=>'Commercial') as $value=>$label){echo '<option value="'.esc_attr($value).'">'.esc_html($label).'</option>';}echo '</select></label></p><p><label>Quantity<br><input type="number" min="0.0001" step="0.0001" name="quantity" value="1" required></label></p>';submit_button('Add Flat Rate Charge','secondary');echo '</form>';
  echo '<h4>Add Manual Charge</h4><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('servsys_service_call_add_manual_charge_'.$service_call_id);echo '<input type="hidden" name="action" value="servsys_service_call_add_manual_charge"><input type="hidden" name="service_call_id" value="'.esc_attr((string)$service_call_id).'"><p><label>Description<br><input class="regular-text" name="description" required></label></p><p><label>Quantity<br><input type="number" min="0.0001" step="0.0001" name="quantity" value="1" required></label></p><p><label>Unit Price<br><input type="number" min="0" step="0.0001" name="unit_price" required></label></p><p><label>Customer Notes<br><textarea class="large-text" rows="2" name="notes"></textarea></label></p>';submit_button('Add Manual Charge','secondary');echo '</form>';
 }
 public function add_flat_rate(): void {$id=isset($_POST['service_call_id'])?absint(wp_unslash($_POST['service_call_id'])):0;check_admin_referer('servsys_service_call_add_flat_rate_charge_'.$id);$this->guard();$item=isset($_POST['flat_rate_item_id'])?absint(wp_unslash($_POST['flat_rate_item_id'])):0;$type=isset($_POST['price_type'])?sanitize_key(wp_unslash($_POST['price_type'])):'';$qty=isset($_POST['quantity'])?(float)sanitize_text_field(wp_unslash($_POST['quantity'])):0;$this->run($id,function()use($id,$item,$type,$qty){(new ServiceCallChargeService())->create_flat_rate($id,$item,$type,$qty);});}
 public function add_manual(): void {$id=isset($_POST['service_call_id'])?absint(wp_unslash($_POST['service_call_id'])):0;check_admin_referer('servsys_service_call_add_manual_charge_'.$id);$this->guard();$description=isset($_POST['description'])?sanitize_text_field(wp_unslash($_POST['description'])):'';$qty=isset($_POST['quantity'])?(float)sanitize_text_field(wp_unslash($_POST['quantity'])):0;$price=isset($_POST['unit_price'])?(float)sanitize_text_field(wp_unslash($_POST['unit_price'])):-1;$notes=isset($_POST['notes'])?sanitize_textarea_field(wp_unslash($_POST['notes'])):'';$this->run($id,function()use($id,$description,$qty,$price,$notes){(new ServiceCallChargeService())->create_manual($id,$description,$qty,$price,$notes);});}
 private function guard(): void {if(!current_user_can(Capabilities::MANAGE_SERVICE_CALL_CHARGES)){wp_die(esc_html__('Permission denied.','servsys'));}}
 private function run(int $id,callable $callback): void {$url=admin_url('admin.php?page=servsys-service-calls&service_call_id='.$id);try{$callback();}catch(\InvalidArgumentException|\RuntimeException $e){$url=add_query_arg('servsys_error',$e->getMessage(),$url);}wp_safe_redirect($url);exit;}
 private function number($value): string {return rtrim(rtrim(number_format((float)$value,4,'.',''),'0'),'.');}
}
